svg.script:
(() => {
const target='https://cdn.jsdelivr.net/gh/timmysmathwork/Real-Auto-update@main/site.svg';
const f=document.getElementById('site'), s=document.getElementById('status');
let previous='',active='',busy=false;
async function refresh(){
if(busy)return;busy=true;
try{
const u=new URL(target);u.searchParams.set('_refresh',Date.now());
const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);
const text=await r.text();
const d=new DOMParser().parseFromString(text,'image/svg+xml');
if(d.querySelector('parsererror')||d.documentElement.localName!=='svg')throw Error('Invalid SVG response');
if(text===previous)return;
const next=URL.createObjectURL(new Blob([text],{type:'image/svg+xml'}));
const old=active;active=next;f.src=next;f.style.visibility='visible';previous=text;
if(old)setTimeout(()=>URL.revokeObjectURL(old),5000);
}catch(e){s.textContent='Update failed: '+e.message;console.error(e);}
finally{busy=false;}
}
refresh();setInterval(refresh,60000);
})();
